router = APIRouter()


def E(request: Request) -> Engine:  # noqa: N802
    return get_engine(request)


def _j(v: Any) -> Any:
    return json.loads(v) if isinstance(v, str) and v[:1] in "[{" else v


# ====================================================================== health / setup / auth
@router.get("/health", tags=["system"])
def health(request: Request) -> dict[str, Any]:
    eng = E(request)
    return {"status": "ok", "engine_version": ENGINE_VERSION, "needs_setup": user_count(eng.db) == 0}


class SetupAdmin(BaseModel):
    username: str = Field(min_length=2, max_length=64)
    display_name: str = Field(min_length=1, max_length=120)
    password: str = Field(min_length=10, max_length=256)
    create_recovery_key: bool = True


@router.get("/setup/status", tags=["system"])
def setup_status(request: Request) -> dict[str, Any]:
    from invoice_analytics.ai import hardware

    eng = E(request)
    return {"needs_admin": user_count(eng.db) == 0, "hardware": hardware.detect(), "data_dir": str(eng.config.data_dir)}


@router.post("/setup/admin", tags=["system"])
def setup_admin(body: SetupAdmin, request: Request) -> dict[str, Any]:
    from invoice_analytics.security.crypto import new_recovery_key
    from invoice_analytics.security.keystore import Keystore

    eng = E(request)
    with eng.db.write_lock:
        if user_count(eng.db) > 0:
            raise HTTPException(409, "setup already completed")
        uid = create_user(eng.db, body.username, body.display_name, "ADMIN", body.password)
    rk = None
    if body.create_recovery_key:
        rk = new_recovery_key()
        Keystore(eng.config.data_dir, eng.config.keystore).write_recovery(eng.keys, rk)
        audit.record(eng.db, "RECOVERY_KEY_CREATED", user_id=uid, entity_type="keystore")
    return {
        "user_id": uid,
        "recovery_key": rk,
        "recovery_key_notice": (
            "Shown once. Print it and store it securely; it can restore backups on a new machine." if rk else None
        ),
    }


class Login(BaseModel):
    username: str
    password: str


@router.get("/auth/mode", tags=["auth"])
def auth_mode(request: Request) -> dict[str, Any]:
    return {"require_login": bool(E(request).settings.get("security.require_login", False))}


@router.post("/auth/auto", tags=["auth"])
def auth_auto(request: Request) -> dict[str, Any]:
    """Sign in as the primary admin without a password, only when sign-in is not required.
    The per-launch bearer token still protects this endpoint from other local processes."""
    eng = E(request)
    if eng.settings.get("security.require_login", False):
        raise HTTPException(403, "sign-in is required")
    with eng.db.write_lock:
        uid = primary_admin_id(eng.db)
    s = get_sessions(request).open_session(uid, idle_seconds=0)
    return {"session_token": s.token, "user": s.as_dict(), "idle_seconds": 0}


@router.post("/auth/login", tags=["auth"])
def login(body: Login, request: Request) -> dict[str, Any]:
    try:
        s = get_sessions(request).login(body.username, body.password)
    except AuthError as e:
        raise HTTPException(401, str(e)) from e
    return {"session_token": s.token, "user": s.as_dict(), "idle_seconds": get_sessions(request).idle_seconds}


@router.post("/auth/logout", tags=["auth"])
def logout(request: Request, s: Session = Viewer) -> dict[str, Any]:
    get_sessions(request).logout(s.token)
    return {"ok": True}


@router.get("/auth/me", tags=["auth"])
def me(s: Session = Viewer) -> dict[str, Any]:
    return s.as_dict()


@router.post("/auth/ping", tags=["auth"])
def ping(s: Session = Viewer) -> dict[str, Any]:
    """Keeps the session alive while the user is active (UI calls this on input)."""
    return {"ok": True}


