class NewUser(BaseModel):
    username: str = Field(min_length=2, max_length=64)
    display_name: str
    role: Literal["ADMIN", "REVIEWER", "VIEWER"]
    password: str = Field(min_length=10)


class PatchUser(BaseModel):
    display_name: str | None = None
    role: Literal["ADMIN", "REVIEWER", "VIEWER"] | None = None
    active: bool | None = None
    password: str | None = Field(None, min_length=10)


@router.get("/users", tags=["users"])
def list_users(request: Request, s: Session = Admin) -> list[dict[str, Any]]:
    return E(request).db.query("SELECT id, username, display_name, role, active, last_login_at FROM users ORDER BY id")


@router.post("/users", tags=["users"])
def add_user(body: NewUser, request: Request, s: Session = Admin) -> dict[str, Any]:
    try:
        uid = create_user(E(request).db, body.username, body.display_name, body.role, body.password, actor_id=s.user_id)
    except Exception as e:  # noqa: BLE001
        raise HTTPException(400, f"could not create user: {type(e).__name__}") from e
    return {"id": uid}


@router.patch("/users/{uid}", tags=["users"])
def patch_user(uid: int, body: PatchUser, request: Request, s: Session = Admin) -> dict[str, Any]:
    from invoice_analytics.security.passwords import hash_password

    eng = E(request)
    before = eng.db.one("SELECT id, display_name, role, active FROM users WHERE id=?", (uid,))
    if before is None:
        raise HTTPException(404, "user not found")
    sets, vals = [], []
    for k in ("display_name", "role", "active"):
        v = getattr(body, k)
        if v is not None:
            sets.append(f"{k}=?")
            vals.append(int(v) if isinstance(v, bool) else v)
    if body.password:
        sets.append("password_hash=?")
        vals.append(hash_password(body.password))
    if sets:
        with eng.db.tx() as c:
            c.execute(
                f"UPDATE users SET {', '.join(sets)}, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=?",
                [*vals, uid],
            )
            audit.record(
                eng.db,
                "USER_UPDATE",
                user_id=s.user_id,
                entity_type="user",
                entity_id=uid,
                before=before,
                after={k: getattr(body, k) for k in ("display_name", "role", "active")}
                | {"password_changed": bool(body.password)},
                conn=c,
            )
    return {"ok": True}


# ====================================================================== ingest
@router.post("/ingest/files", tags=["ingest"])
async def ingest_files(
    request: Request,
    files: list[UploadFile] = File(...),
    options: str = Form("{}"),
    template_id: int | None = Form(None),
    mapping: str | None = Form(None),
    s: Session = Reviewer,
) -> dict[str, Any]:
    jobs = request.app.state.ingest_jobs
    opts = json.loads(options or "{}")
    mp = json.loads(mapping) if mapping else None
    out = []
    for f in files:
        data = await f.read()
        out.append(
            jobs.submit(
                f.filename or "upload", data, user_id=s.user_id, options=opts, mapping=mp, template_id=template_id
            ).public()
        )
    return {"jobs": out}


@router.get("/ingest/jobs", tags=["ingest"])
def ingest_jobs(request: Request, s: Session = Viewer) -> list[dict[str, Any]]:
    return request.app.state.ingest_jobs.list()  # type: ignore[no-any-return]


@router.get("/ingest/jobs/{job_id}", tags=["ingest"])
def ingest_job(job_id: int, request: Request, s: Session = Viewer) -> dict[str, Any]:
    j = request.app.state.ingest_jobs.get(job_id)
    if j is None:
        raise HTTPException(404, "job not found")
    return j.public()  # type: ignore[no-any-return]


class MappingSubmit(BaseModel):
    mapping: dict[str, str]
    options: dict[str, Any] = {}
    save_template_name: str | None = None


@router.post("/ingest/jobs/{job_id}/mapping", tags=["ingest"])
def ingest_job_mapping(job_id: int, body: MappingSubmit, request: Request, s: Session = Reviewer) -> dict[str, Any]:
    from invoice_analytics.ingest.service import save_template

    jobs = request.app.state.ingest_jobs
    j = jobs.get(job_id)
    if j is None:
        raise HTTPException(404, "job not found or expired")
    tid = None
    if body.save_template_name:
        headers = (j.result or {}).get("headers")
        tid = save_template(E(request), body.save_template_name, headers, body.mapping, body.options, s.user_id)
    return jobs.resubmit_with_mapping(job_id, body.mapping, body.options, tid).public()  # type: ignore[no-any-return]


