# ====================================================================== documents / extraction drafts
@router.get("/documents", tags=["documents"])
def documents(
    request: Request, status: str | None = None, limit: int = Query(100, le=500), s: Session = Viewer
) -> list[dict[str, Any]]:
    return E(request).db.query(
        "SELECT d.id, d.source_path, d.mime, d.page_count, d.ingest_method, d.ingest_status, d.ingest_confidence,"
        " d.ingested_at, (SELECT id FROM extraction_drafts x WHERE x.document_id=d.id ORDER BY id DESC LIMIT 1) AS draft_id,"
        " (SELECT COUNT(*) FROM invoices i WHERE i.document_id=d.id) AS invoices"
        " FROM documents d WHERE (? IS NULL OR d.ingest_status=?) ORDER BY d.id DESC LIMIT ?",
        (status, status, limit),
    )


@router.get("/documents/{doc_id}/content", tags=["documents"])
def document_content(doc_id: int, request: Request, s: Session = Reviewer) -> Response:
    eng = E(request)
    row = eng.db.one(
        "SELECT b.data, d.mime FROM document_blobs b JOIN documents d ON d.id=b.document_id WHERE b.document_id=?",
        (doc_id,),
    )
    if row is None:
        raise HTTPException(404, "no stored content for this document")
    audit.record(eng.db, "VIEW_PHI", user_id=s.user_id, entity_type="document", entity_id=doc_id)
    media = "application/pdf" if row["mime"] == "PDF" else "image/png"
    return Response(row["data"], media_type=media, headers={"Cache-Control": "no-store"})


@router.get("/drafts/{draft_id}", tags=["documents"])
def get_draft(draft_id: int, request: Request, s: Session = Reviewer) -> dict[str, Any]:
    eng = E(request)
    d = eng.db.one("SELECT * FROM extraction_drafts WHERE id=?", (draft_id,))
    if d is None:
        raise HTTPException(404, "draft not found")
    d["fields"] = json.loads(d["fields"])
    ai = eng.db.one(
        "SELECT id, status, output, created_at FROM ai_suggestions WHERE target_type='EXTRACTION_DRAFT'"
        " AND target_id=? ORDER BY id DESC LIMIT 1",
        (draft_id,),
    )
    if ai:
        ai["output"] = _j(ai["output"])
    d["ai_suggestion"] = ai
    audit.record(eng.db, "VIEW_PHI", user_id=s.user_id, entity_type="extraction_draft", entity_id=draft_id)
    return d


class DraftAccept(BaseModel):
    invoice: dict[str, Any] = {}
    lines: list[dict[str, Any]] | None = None
    options: dict[str, Any] = {}
    from_ai: bool = False


@router.post("/drafts/{draft_id}/accept", tags=["documents"])
def accept_draft_ep(draft_id: int, body: DraftAccept, request: Request, s: Session = Reviewer) -> dict[str, Any]:
    from invoice_analytics.ingest.pdf.pipeline import accept_draft

    corrected: dict[str, Any] = {"invoice": body.invoice, "from_ai": body.from_ai}
    if body.lines is not None:
        corrected["lines"] = body.lines
    try:
        return accept_draft(E(request), draft_id, corrected, user_id=s.user_id, options=body.options)
    except ValueError as e:
        raise HTTPException(400, str(e)) from e


@router.post("/drafts/{draft_id}/reject", tags=["documents"])
def reject_draft(draft_id: int, request: Request, s: Session = Reviewer) -> dict[str, Any]:
    eng = E(request)
    with eng.db.tx() as c:
        n = c.execute(
            "UPDATE extraction_drafts SET status='REJECTED' WHERE id=? AND status='OPEN'", (draft_id,)
        ).rowcount
        audit.record(
            eng.db, "EXTRACTION_REJECT", user_id=s.user_id, entity_type="extraction_draft", entity_id=draft_id, conn=c
        )
    return {"ok": bool(n)}


# ====================================================================== invoices
@router.get("/invoices", tags=["invoices"])
def invoices(
    request: Request,
    party_id: int | None = None,
    q: str | None = None,
    status: str | None = None,
    date_from: str | None = Query(None, alias="from"),
    date_to: str | None = Query(None, alias="to"),
    min_cents: int | None = None,
    max_cents: int | None = None,
    direction: str | None = None,
    flagged: bool | None = None,
    limit: int = Query(100, le=1000),
    offset: int = 0,
    s: Session = Viewer,
) -> dict[str, Any]:
    where: list[str] = ["i.deleted_at IS NULL"]
    p: list[Any] = []
    if party_id:
        where.append("p.cluster_id=(SELECT cluster_id FROM parties WHERE id=?)")
        p.append(party_id)
    if q:
        from invoice_analytics.normalize import normalize_invoice_number

        where.append("(i.invoice_number_norm LIKE ? OR p.name_norm LIKE ? OR i.po_number LIKE ?)")
        p += [f"%{normalize_invoice_number(q) or q}%", f"%{q.upper()}%", f"%{q}%"]
    for col, val, op in (
        ("i.status", status, "="),
        ("i.invoice_date", date_from, ">="),
        ("i.invoice_date", date_to, "<="),
        ("i.total_cents", min_cents, ">="),
        ("i.total_cents", max_cents, "<="),
        ("i.direction", direction, "="),
    ):
        if val is not None:
            where.append(f"{col}{op}?")
            p.append(val)
    if flagged is not None:
        where.append(
            ("" if flagged else "NOT ") + "EXISTS (SELECT 1 FROM flags f WHERE f.subject_invoice_id=i.id AND f.active=1"
            " AND f.suppressed_by IS NULL AND f.tier IN ('HARD','PROBABLE'))"
        )
    w = " AND ".join(where)
    eng = E(request)
    total = eng.db.scalar(f"SELECT COUNT(*) FROM invoices i JOIN parties p ON p.id=i.party_id WHERE {w}", p)
    rows = eng.db.query(
        f"SELECT i.id, i.direction, i.party_id, p.display_name AS party, i.invoice_number_raw AS invoice_number,"
        f" i.invoice_date, i.invoice_date_raw, i.total_cents, i.status, i.claim_frequency_code, i.needs_attention,"
        f" (SELECT COUNT(*) FROM invoice_lines l WHERE l.invoice_id=i.id) AS line_count,"
        f" (SELECT MAX(CASE f.tier WHEN 'HARD' THEN 4 WHEN 'PROBABLE' THEN 3 WHEN 'WEAK' THEN 2 ELSE 1 END) FROM flags f"
        f"  WHERE f.subject_invoice_id=i.id AND f.active=1 AND f.suppressed_by IS NULL) AS max_tier_rank"
        f" FROM invoices i JOIN parties p ON p.id=i.party_id WHERE {w} ORDER BY i.invoice_date DESC, i.id DESC"
        f" LIMIT ? OFFSET ?",
        [*p, limit, offset],
    )
    return {"total": total, "items": rows}


def invoice_detail(eng: Engine, invoice_id: int, user_id: int | None) -> dict[str, Any]:
    inv = eng.db.one(
        "SELECT i.*, p.display_name AS party, p.cluster_id AS party_cluster, d.source_path, d.ingest_method, d.sha256"
        " FROM invoices i JOIN parties p ON p.id=i.party_id LEFT JOIN documents d ON d.id=i.document_id WHERE i.id=?",
        (invoice_id,),
    )
    if inv is None:
        raise HTTPException(404, "invoice not found")
    fc = eng.field_cipher
    lines = eng.db.query(
        "SELECT l.*, pt.cluster_id AS patient_cluster, pt.first_name_enc, pt.last_name_enc, pt.dob AS patient_dob,"
        " pt.subject_id_enc"
        " FROM invoice_lines l LEFT JOIN patients pt ON pt.id=l.patient_id WHERE l.invoice_id=? ORDER BY l.line_no",
        (invoice_id,),
    )
    for li in lines:
        first = fc.decrypt(li.pop("first_name_enc"), aad="patient.first") if li.get("first_name_enc") else None
        last = fc.decrypt(li.pop("last_name_enc"), aad="patient.last") if li.get("last_name_enc") else None
        li.pop("first_name_enc", None)
        li.pop("last_name_enc", None)
        li.pop("description_embedding", None)
        subj = fc.decrypt(li.pop("subject_id_enc"), aad="patient.subject") if li.get("subject_id_enc") else None
        li.pop("subject_id_enc", None)
        li["patient_name"] = (
            f"{last}, {first}".strip(", ") if (first or last) else (f"Subject {subj}" if subj else None)
        )
        li["modifiers"] = json.loads(li["modifiers"])
        li["dx_codes"] = json.loads(li["dx_codes"])
    inv["lines"] = lines
    inv["flags"] = eng.db.query(
        "SELECT id, rule_id, tier, status, score, suppressed_by, amount_at_risk_cents, subject_type,"
        " json_extract(evidence,'$.summary') AS summary FROM flags WHERE active=1 AND"
        " (subject_invoice_id=? OR EXISTS (SELECT 1 FROM json_each(counterpart_invoice_ids) WHERE value=?))"
        " ORDER BY CASE tier WHEN 'HARD' THEN 0 WHEN 'PROBABLE' THEN 1 WHEN 'WEAK' THEN 2 ELSE 3 END",
        (invoice_id, invoice_id),
    )
    inv["links"] = eng.db.query(
        "SELECT * FROM invoice_links WHERE from_invoice_id=? OR to_invoice_id=?", (invoice_id, invoice_id)
    )
    inv["history"] = [
        audit.decode(r)
        for r in eng.db.query(
            "SELECT ts, action, user_id, after FROM audit_log WHERE entity_type='invoice' AND entity_id=? ORDER BY id",
            (str(invoice_id),),
        )
    ]
    audit.record(eng.db, "VIEW_PHI", user_id=user_id, entity_type="invoice", entity_id=invoice_id)
    return inv


