# ====================================================================== flags / review
_TIER_ORDER = "CASE f.tier WHEN 'HARD' THEN 0 WHEN 'PROBABLE' THEN 1 WHEN 'WEAK' THEN 2 ELSE 3 END"


def _flag_filters(
    tier: str | None,
    rule: str | None,
    status: str | None,
    party: int | None,
    date_from: str | None,
    date_to: str | None,
    include_suppressed: bool,
    min_cents: int | None,
) -> tuple[str, list[Any]]:
    where: list[str] = ["f.active=1"]
    p: list[Any] = []
    if not include_suppressed:
        where.append("f.suppressed_by IS NULL")
    if tier:
        tiers = tier.split(",")
        where.append(f"f.tier IN ({','.join('?' * len(tiers))})")
        p += tiers
    else:
        where.append("f.tier IN ('HARD','PROBABLE')")
    if rule:
        rules = rule.split(",")
        where.append(f"f.rule_id IN ({','.join('?' * len(rules))})")
        p += rules
    if status:
        sts = status.split(",")
        where.append(f"f.status IN ({','.join('?' * len(sts))})")
        p += sts
    if party:
        where.append(
            "f.party_id IN (SELECT id FROM parties WHERE cluster_id=(SELECT cluster_id FROM parties WHERE id=?))"
        )
        p.append(party)
    if date_from:
        where.append("i.invoice_date>=?")
        p.append(date_from)
    if date_to:
        where.append("i.invoice_date<=?")
        p.append(date_to)
    if min_cents is not None:
        where.append("f.amount_at_risk_cents>=?")
        p.append(min_cents)
    return " AND ".join(where), p


# What a flag compares the record with: another invoice (billed before), lines of the same invoice,
# or nothing (a limit breached on one record). Cross-invoice flags are reviewed first.
_SCOPE_SQL = (
    "(CASE WHEN f.counterpart_invoice_ids IN ('[]', '') THEN 'SINGLE'"
    " WHEN json(f.counterpart_invoice_ids) = json_array(f.subject_invoice_id) THEN 'WITHIN' ELSE 'ACROSS' END)"
)
_SCOPE_ORDER = f"CASE {_SCOPE_SQL} WHEN 'ACROSS' THEN 0 WHEN 'SINGLE' THEN 1 ELSE 2 END"


@router.get("/flags", tags=["flags"])
def flags(
    request: Request,
    tier: str | None = None,
    rule: str | None = None,
    status: str | None = "OPEN",
    party: int | None = None,
    date_from: str | None = Query(None, alias="from"),
    date_to: str | None = Query(None, alias="to"),
    sort: str = "priority",
    include_suppressed: bool = False,
    min_cents: int | None = None,
    scope: Literal["ACROSS", "WITHIN", "SINGLE"] | None = None,
    limit: int = Query(200, le=2000),
    offset: int = 0,
    s: Session = Viewer,
) -> dict[str, Any]:
    w, p = _flag_filters(tier, rule, status, party, date_from, date_to, include_suppressed, min_cents)
    if scope:
        w += f" AND {_SCOPE_SQL} = ?"
        p.append(scope)
    order = {
        "priority": f"{_TIER_ORDER}, {_SCOPE_ORDER}, f.score DESC, f.amount_at_risk_cents DESC",
        "amount": "f.amount_at_risk_cents DESC",
        "newest": "f.id DESC",
        "date": "i.invoice_date DESC",
    }.get(sort, _TIER_ORDER)
    eng = E(request)
    total = eng.db.scalar(f"SELECT COUNT(*) FROM flags f JOIN invoices i ON i.id=f.subject_invoice_id WHERE {w}", p)
    rows = eng.db.query(
        f"SELECT f.id, f.rule_id, f.tier, f.base_tier, f.score, f.status, f.subject_type, f.subject_id, f.subject_invoice_id,"
        f" f.counterpart_invoice_ids, f.amount_at_risk_cents, f.suppressed_by, f.downgraded_by, f.created_at,"
        f" json_extract(f.evidence,'$.summary') AS summary, json_extract(f.evidence,'$.title') AS title,"
        f" i.invoice_number_raw AS invoice_number, i.invoice_date, pa.display_name AS party, {_SCOPE_SQL} AS scope,"
        f" (SELECT COUNT(*) FROM flags s WHERE s.subject_invoice_id=f.subject_invoice_id AND s.id<>f.id"
        f"  AND s.counterpart_invoice_ids=f.counterpart_invoice_ids AND s.active=1 AND s.suppressed_by IS NULL"
        f"  AND s.status=f.status) AS sibling_count,"
        f" (SELECT json_extract(output,'$.verdict') FROM ai_suggestions a WHERE a.target_type='FLAG' AND a.target_id=f.id"
        f"  AND a.task='TRIAGE' AND a.status='OK' ORDER BY a.id DESC LIMIT 1) AS ai_verdict"
        f" FROM flags f JOIN invoices i ON i.id=f.subject_invoice_id JOIN parties pa ON pa.id=i.party_id"
        f" WHERE {w} ORDER BY {order} LIMIT ? OFFSET ?",
        [*p, limit, offset],
    )
    for r in rows:
        r["counterpart_invoice_ids"] = json.loads(r["counterpart_invoice_ids"])
    return {"total": total, "items": rows}


