        f" json_extract(f.evidence,'$.summary') AS summary FROM flags f JOIN invoices i ON i.id=f.subject_invoice_id"
        f" JOIN parties pa ON pa.id=i.party_id WHERE {w} ORDER BY {_TIER_ORDER}, f.score DESC",
