@router.get("/flags/{flag_id}", tags=["flags"])
def flag_detail(flag_id: int, request: Request, s: Session = Viewer) -> dict[str, Any]:
    from invoice_analytics.review import history

    eng = E(request)
    f = eng.db.one("SELECT * FROM flags WHERE id=?", (flag_id,))
    if f is None:
        raise HTTPException(404, "flag not found")
    f["evidence"] = json.loads(f["evidence"])
    f["counterpart_ids"] = json.loads(f["counterpart_ids"])
    f["counterpart_invoice_ids"] = json.loads(f["counterpart_invoice_ids"])
    f["subject_invoice"] = invoice_detail(eng, f["subject_invoice_id"], s.user_id)
    f["counterpart_invoices"] = [invoice_detail(eng, i, s.user_id) for i in f["counterpart_invoice_ids"][:4]]
    f["reviews"] = history(eng, flag_id)
    sugg = eng.db.query(
        "SELECT id, task, status, output, model_id, prompt_version, latency_ms, created_at"
        " FROM ai_suggestions WHERE target_type='FLAG' AND target_id=? ORDER BY id DESC",
        (flag_id,),
    )
    for a in sugg:
        a["output"] = _j(a["output"])
    f["ai"] = {
        "explain": next((a for a in sugg if a["task"] == "EXPLAIN"), None),
        "triage": next((a for a in sugg if a["task"] == "TRIAGE"), None),
    }
    f["other_flags_on_subject"] = eng.db.query(
        "SELECT id, rule_id, tier, status FROM flags WHERE subject_invoice_id=? AND id<>? AND active=1 AND suppressed_by IS NULL",
        (f["subject_invoice_id"], flag_id),
    )
    # opening a flag bumps its explanation to the front of the AI queue
    if eng.settings.get("ai.tier", "OFF") != "OFF" and f["ai"]["explain"] is None:
        from invoice_analytics.ai.jobs import PRIORITY

        eng.jobs.enqueue("AI_EXPLAIN", {"flag_id": flag_id}, PRIORITY["UI_EXPLAIN"])
    return f


