@router.get("/patients/link-suggestions", tags=["identity"])
def patient_suggestions(
    request: Request, status: str = "OPEN", show_names: bool = False, s: Session = Reviewer
) -> list[dict[str, Any]]:
    eng = E(request)
    rows = _suggestions(eng, "PATIENT", status)
    if show_names:
        fc = eng.field_cipher
        ids = {i for r in rows for i in (r["left_id"], r["right_id"])}
        if ids:
            ph = ",".join("?" * len(ids))
            pts = {
                p["id"]: p
                for p in eng.db.query(
                    f"SELECT id, first_name_enc, last_name_enc, dob, sex, zip5 FROM patients WHERE id IN ({ph})",
                    list(ids),
                )
            }
            for r in rows:
                for side in ("left", "right"):
                    p = pts.get(r[f"{side}_id"], {})
                    r[side] = {
                        "name": f"{fc.decrypt(p.get('last_name_enc'), aad='patient.last') or ''}, "
                        f"{fc.decrypt(p.get('first_name_enc'), aad='patient.first') or ''}",
                        "dob": p.get("dob"),
                        "sex": p.get("sex"),
                        "zip5": p.get("zip5"),
                    }
            audit.record(
                eng.db,
                "VIEW_PHI",
                user_id=s.user_id,
                entity_type="patient_link_suggestions",
                after={"pairs": len(rows)},
            )
    return rows


