@router.get("/rules", tags=["rules"])
def rules(request: Request, s: Session = Viewer) -> list[dict[str, Any]]:
    from invoice_analytics.reports import rule_precision
    from invoice_analytics.rules import ALL_RULES

    eng = E(request)
    prec = {r["rule_id"]: r for r in rule_precision(eng)}
    counts = {
        r["rule_id"]: r["n"]
        for r in eng.db.query(
            "SELECT rule_id, COUNT(*) AS n FROM flags WHERE active=1 AND suppressed_by IS NULL GROUP BY rule_id"
        )
    }
    out = []
    for r in ALL_RULES:
        key = f"rules.{r.rule_id}"
        out.append(
            {
                **r.describe(),
                "config": eng.settings.get(key),
                "config_version": eng.settings.version(key),
                "active_flags": counts.get(r.rule_id, 0),
                "precision": prec[r.rule_id]["precision"],
                "reviewed": prec[r.rule_id]["reviewed"],
            }
        )
    sups = [
        {"rule_id": k.split(".", 1)[1], "config": v} for k, v in eng.settings.all().items() if k.startswith("suppress.")
    ]
    return out + [{"rule_id": x["rule_id"], "kind": "suppression", "config": x["config"]} for x in sups]


@router.patch("/rules/{rule_id}", tags=["rules"])
def patch_rule(rule_id: str, changes: dict[str, Any], request: Request, s: Session = Admin) -> dict[str, Any]:
    eng = E(request)
    key = f"suppress.{rule_id}" if rule_id.startswith("SUP-") else f"rules.{rule_id}"
    if eng.settings.get(key) is None:
        raise HTTPException(404, "unknown rule")
    allowed = set(eng.settings.get(key).keys())
    bad = set(changes) - allowed
    if bad:
        raise HTTPException(400, f"unknown settings: {sorted(bad)}")
    ver = eng.settings.set(key, changes, s.user_id)
    return {
        "rule_id": rule_id,
        "version": ver,
        "config": eng.settings.get(key),
        "note": "Run a full sweep to apply the change to existing records.",
    }


