def _ref_edit(
    eng: Engine, table: str, action: str, user_id: int, row: dict[str, Any] | None = None, rid: int | None = None
) -> dict[str, Any]:
    with eng.db.tx() as c:
        if action == "add" and row is not None:
            cols = list(row)
            rid = int(
                c.execute(
                    f"INSERT INTO {table}({','.join(cols)}) VALUES ({','.join('?' * len(cols))})",
                    [row[k] for k in cols],
                ).lastrowid
            )
        else:
            c.execute(f"DELETE FROM {table} WHERE id=?", (rid,))
        audit.record(
            eng.db,
            "REFDATA_EDIT",
            user_id=user_id,
            entity_type=table,
            entity_id=rid,
            after={"action": action, "row": row},
            conn=c,
        )
    eng.store.reload_refdata()
    return {"id": rid}


