@router.get("/reports/{name}", tags=["reports"])
def report(
    name: str,
    request: Request,
    format: str = "json",
    period: str = "month",
    date_from: str | None = Query(None, alias="from"),
    date_to: str | None = Query(None, alias="to"),
    s: Session = Viewer,
) -> Any:
    from invoice_analytics import reports as rp

    eng = E(request)
    if name not in rp.REPORTS:
        raise HTTPException(404, "unknown report")
    rows = rp.duplicates_by_period(eng, period, date_from, date_to) if name == "duplicates" else rp.REPORTS[name](eng)
    if format == "json":
        return rows
    audit.record(
        eng.db,
        "EXPORT",
        user_id=s.user_id,
        entity_type="report",
        entity_id=name,
        after={"format": format, "rows": len(rows)},
    )
    if format == "csv":
        return Response(
            rp.to_csv(rows),
            media_type="text/csv",
            headers={"Content-Disposition": f"attachment; filename=invoice-analytics-{name}.csv"},
        )
    if format == "pdf":
        return Response(
            rp.to_pdf(f"ABM Invoice Analytics report: {name}", rows),
            media_type="application/pdf",
            headers={"Content-Disposition": f"attachment; filename=invoice-analytics-{name}.pdf"},
        )
    raise HTTPException(400, "format must be json, csv or pdf")


@router.get("/audit", tags=["audit"])
def audit_list(
    request: Request,
    action: str | None = None,
    entity_type: str | None = None,
    user_id: int | None = None,
    date_from: str | None = Query(None, alias="from"),
    date_to: str | None = Query(None, alias="to"),
    limit: int = Query(200, le=2000),
    offset: int = 0,
    s: Session = Admin,
) -> dict[str, Any]:
    where: list[str] = ["1=1"]
    p: list[Any] = []
    for col, v, op in (
        ("action", action, "="),
        ("entity_type", entity_type, "="),
        ("user_id", user_id, "="),
        ("ts", date_from, ">="),
        ("ts", date_to, "<="),
    ):
        if v is not None:
            where.append(f"a.{col}{op}?")
            p.append(v)
    eng = E(request)
    w = " AND ".join(where)
    rows = eng.db.query(
        f"SELECT a.*, u.username FROM audit_log a LEFT JOIN users u ON u.id=a.user_id WHERE {w}"
        f" ORDER BY a.id DESC LIMIT ? OFFSET ?",
        [*p, limit, offset],
    )
    return {
        "total": eng.db.scalar(f"SELECT COUNT(*) FROM audit_log a WHERE {w}", p),
        "items": [audit.decode(r) for r in rows],
    }


@router.post("/audit/verify", tags=["audit"])
def audit_verify(request: Request, s: Session = Admin) -> dict[str, Any]:
    eng = E(request)
    res = audit.verify(eng.db).as_dict()
    audit.record(eng.db, "AUDIT_VERIFY", user_id=s.user_id, entity_type="audit_log", after=res)
    return res


# ====================================================================== settings / backup / retention
@router.get("/settings", tags=["settings"])
def get_settings(request: Request, s: Session = Viewer) -> dict[str, Any]:
    return {k: v for k, v in E(request).settings.all().items() if not k.startswith(("rules.", "suppress."))}


@router.patch("/settings", tags=["settings"])
def patch_settings(changes: dict[str, Any], request: Request, s: Session = Admin) -> dict[str, Any]:
    eng = E(request)
    blocked = {"ai.tier"}  # use /ai/tier (hardware check)
    for k, v in changes.items():
        if k in blocked or k.startswith(("rules.", "suppress.")):
            raise HTTPException(400, f"{k} must be changed through its dedicated endpoint")
        if k == "ingest.watched_folders":
            v = [str(Path(x).expanduser()) for x in v if Path(x).expanduser().is_dir()]
        try:
            eng.settings.set(k, v, s.user_id)
        except KeyError as e:
            raise HTTPException(400, str(e)) from e
    if "security.session_idle_seconds" in changes:
        get_sessions(request).idle_seconds = int(changes["security.session_idle_seconds"])
    return {"ok": True}


class BackupBody(BaseModel):
    dest_dir: str | None = None
    recovery_key: str | None = None


@router.post("/backup", tags=["backup"])
def backup(body: BackupBody, request: Request, s: Session = Admin) -> dict[str, Any]:
    from invoice_analytics.backup import create_backup

    eng = E(request)
    dest = Path(body.dest_dir or eng.settings.get("backup.folder") or (eng.config.data_dir / "backups")).expanduser()
    out = create_backup(eng, dest, user_id=s.user_id, recovery_key=body.recovery_key)
    return {"path": str(out), "bytes": out.stat().st_size}


class RestoreBody(BaseModel):
    path: str
    recovery_key: str | None = None


@router.post("/restore", tags=["backup"])
def restore(body: RestoreBody, request: Request, s: Session = Admin) -> dict[str, Any]:
    import os
    import threading

    from invoice_analytics.backup import BackupError, restore_backup

    eng = E(request)
    p = Path(body.path).expanduser()
    if p.suffix != ".vbak" or not p.is_file():
        raise HTTPException(400, "choose a .vbak backup file")
    audit.record(eng.db, "RESTORE_START", user_id=s.user_id, entity_type="backup", entity_id=p.name)
    # Quiesce everything that holds a DB connection before the file is swapped (required on Windows).
    request.app.state.ingest_jobs.stop()
    try:
        res = restore_backup(eng, p, user_id=s.user_id, recovery_key=body.recovery_key)
    except BackupError as e:
        raise HTTPException(400, str(e)) from e
    # The engine exits after replying; the desktop shell restarts it on the restored database.
    threading.Timer(0.5, lambda: os._exit(75)).start()
    return {**res, "restart_required": True}


class RetentionBody(BaseModel):
    years: int = Field(ge=1, le=50)
    hard_delete: bool = False
    confirm: bool = False


@router.post("/retention/preview", tags=["backup"])
def retention_prev(body: RetentionBody, request: Request, s: Session = Admin) -> dict[str, Any]:
    from invoice_analytics.backup import retention_preview

    return retention_preview(E(request), body.years)


@router.post("/retention/apply", tags=["backup"])
def retention_apply_ep(body: RetentionBody, request: Request, s: Session = Admin) -> dict[str, Any]:
    from invoice_analytics.backup import retention_apply

    if not body.confirm:
        raise HTTPException(400, "set confirm=true to apply the retention action")
    return retention_apply(E(request), body.years, user_id=s.user_id, hard_delete=body.hard_delete)


@router.get("/jobs", tags=["system"])
def jobs(request: Request, s: Session = Viewer) -> list[dict[str, Any]]:
    rows = E(request).db.query(
        "SELECT id, kind, priority, status, attempts, error, created_at, started_at, finished_at"
        " FROM jobs ORDER BY id DESC LIMIT 100"
    )
    return rows
